"""Dynamic LexBFS ordering.

Strategy:
- init: static LexBFS via partition refinement (O(n+m)).
- insert_edge: try to repair the existing ordering by moving u and v to
  their correct positions.  If the repair fails the (LB) 4-point
  certificate, fall back to a full recompute.
- delete_edge: try to repair the existing ordering by moving u and v to
  their correct positions.  If the repair fails the (LB) 4-point
  certificate, fall back to a full recompute.

The (LB) certificate (Corneil-Krueger): for all positions a < b < c with
ac in E and ab not in E, there exists d < a with db in E and dc not in E.
"""


def _lexbfs(graph):
    """Static LexBFS via partition refinement. Returns the ordering list."""
    n = len(graph)
    if n == 0:
        return []

    # order: current ordering of all vertices
    order = list(range(n))
    # blocks: list of [start, end) ranges in `order`
    blocks = [[0, n]]

    for _ in range(n):
        # pick the first vertex of the first block
        s = order[blocks[0][0]]

        # refine: split each block AFTER the first into (neighbors of s,
        # non-neighbors of s), neighbors first.  The first block is
        # consumed (its first vertex is s); the rest are rebuilt.
        new_order = [s]
        new_blocks = []
        for (lo, hi) in blocks[1:]:
            nbrs = []
            nonbrs = []
            for j in range(lo, hi):
                v = order[j]
                if graph[s][v]:
                    nbrs.append(v)
                else:
                    nonbrs.append(v)
            start = len(new_order)
            new_order.extend(nbrs)
            new_order.extend(nonbrs)
            end = len(new_order)
            if end > start:
                new_blocks.append([start, end])
        order = new_order
        blocks = new_blocks
        if not blocks:
            break

    return order


def _is_lexbfs(order, graph):
    """Check the (LB) 4-point certificate. Returns True if valid."""
    n = len(order)
    for ia in range(n):
        a = order[ia]
        for ib in range(ia + 1, n):
            b = order[ib]
            for ic in range(ib + 1, n):
                c = order[ic]
                if graph[a][c] and not graph[a][b]:
                    found = False
                    for id_ in range(ia):
                        d = order[id_]
                        if graph[d][b] and not graph[d][c]:
                            found = True
                            break
                    if not found:
                        return False
    return True


def _try_repair(order, graph, u, v):
    """Try to repair the ordering after an edge update involving u and v.

    The update only changes the neighbor sets of u and v.  In a LexBFS
    ordering, the relative order of u and v is determined by their labels.
    After the update, the only possible change is the relative order of
    u and v.  So we try: keep current order, or swap u and v.
    """
    n = len(order)
    if n == 0:
        return None
    pos = {v: i for i, v in enumerate(order)}
    if u not in pos or v not in pos:
        return None
    pu, pv = pos[u], pos[v]

    candidates = [list(order)]
    swapped = list(order)
    swapped[pu], swapped[pv] = swapped[pv], swapped[pu]
    candidates.append(swapped)

    for cand in candidates:
        if _is_lexbfs(cand, graph):
            return cand
    return None


def init(graph):
    order = _lexbfs(graph)
    return {'ordering': order}


def insert_edge(graph, edge, state):
    u, v = edge
    order = state['ordering']
    repaired = _try_repair(order, graph, u, v)
    if repaired is not None:
        return {'ordering': repaired}
    return {'ordering': _lexbfs(graph)}


def delete_edge(graph, edge, state):
    u, v = edge
    order = state['ordering']
    repaired = _try_repair(order, graph, u, v)
    if repaired is not None:
        return {'ordering': repaired}
    return {'ordering': _lexbfs(graph)}

"""Dynamic LexBFS ordering.

Strategy: maintain a valid LexBFS ordering incrementally.

- init: static partition-refinement LexBFS (Habib-McConnell-Paul-Viennot),
  O(n+m) via adjacency lists.
- insert_edge(u,v): if the current ordering is still valid (checked with the
  (LB) 4-point property), keep it. Otherwise recompute from scratch.
- delete_edge(u,v): same check-then-recompute scheme.

The 4-point check is O(n^3) in the worst case but early-exits on the first
violation; for sparse graphs it is usually far cheaper than a full recompute.
"""


def _adj_lists(graph):
    n = len(graph)
    adj = [set() for _ in range(n)]
    for i in range(n):
        row = graph[i]
        for j in range(i + 1, n):
            if row[j]:
                adj[i].add(j)
                adj[j].add(i)
    return adj


def _lexbfs(adj):
    """Static LexBFS via partition refinement. Returns ordering list."""
    n = len(adj)
    if n == 0:
        return []

    # HMPV algorithm:
    # - Start with all vertices in one bucket.
    # - Pick first vertex s from first bucket, remove it.
    # - Split each remaining bucket into N(s) and Nbar(s), N(s) first.
    # - Repeat until all vertices are picked.

    buckets = [list(range(n))]
    order = []

    for _ in range(n):
        s = buckets[0][0]
        order.append(s)
        buckets[0] = buckets[0][1:]
        if not buckets[0]:
            buckets = buckets[1:]

        new_buckets = []
        for b in buckets:
            n_part = [v for v in b if v in adj[s]]
            nb_part = [v for v in b if v not in adj[s]]
            if n_part:
                new_buckets.append(n_part)
            if nb_part:
                new_buckets.append(nb_part)
        buckets = new_buckets

    return order


def _is_valid_lexbfs(order, adj):
    """Check the (LB) 4-point property.
    For all positions a < b < c with ac in E and ab not in E,
    there exists d < a with db in E and dc not in E.
    """
    n = len(order)
    for a in range(n):
        va = order[a]
        for b in range(a + 1, n):
            vb = order[b]
            if va in adj[vb]:
                continue  # ab in E, no constraint
            for c in range(b + 1, n):
                vc = order[c]
                if va not in adj[vc]:
                    continue  # ac not in E, no constraint
                # ac in E, ab not in E: need d < a with db in E and dc not in E
                found = False
                for d in range(a):
                    vd = order[d]
                    if vb in adj[vd] and vc not in adj[vd]:
                        found = True
                        break
                if not found:
                    return False
    return True


def _recompute(graph):
    adj = _adj_lists(graph)
    order = _lexbfs(adj)
    return {'ordering': order, 'adj': adj}


def init(graph):
    return _recompute(graph)


def insert_edge(graph, edge, state):
    u, v = edge
    state['adj'][u].add(v)
    state['adj'][v].add(u)
    if _is_valid_lexbfs(state['ordering'], state['adj']):
        return state
    return _recompute(graph)


def delete_edge(graph, edge, state):
    u, v = edge
    state['adj'][u].discard(v)
    state['adj'][v].discard(u)
    if _is_valid_lexbfs(state['ordering'], state['adj']):
        return state
    return _recompute(graph)

"""Dynamic LexBFS ordering.

Strategy:
- init: static LexBFS via partition refinement (O(n+m)).
- insert_edge: try to repair the existing ordering by moving u and v to
  their correct positions.  If the repair fails the (LB) 4-point
  certificate, fall back to a full recompute.
- delete_edge: recompute from scratch.

The (LB) certificate (Corneil-Krueger): for all positions a < b < c with
ac in E and ab not in E, there exists d < a with db in E and dc not in E.
"""


def _lexbfs(graph):
    """Static LexBFS via partition refinement. Returns the ordering list."""
    n = len(graph)
    if n == 0:
        return []

    # order: current ordering of all vertices
    order = list(range(n))
    # blocks: list of [start, end) ranges in `order`
    blocks = [[0, n]]

    for _ in range(n):
        # pick the first vertex of the first block
        s = order[blocks[0][0]]

        # refine: split each block into (neighbors of s, non-neighbors of s)
        # neighbors first.  Rebuild the order.
        new_order = []
        new_blocks = []
        for (lo, hi) in blocks:
            nbrs = []
            nonbrs = []
            for j in range(lo, hi):
                v = order[j]
                if graph[s][v]:
                    nbrs.append(v)
                else:
                    nonbrs.append(v)
            start = len(new_order)
            new_order.extend(nbrs)
            new_order.extend(nonbrs)
            end = len(new_order)
            if end > start:
                new_blocks.append([start, end])
        order = new_order
        blocks = new_blocks

    return order


def _is_lexbfs(order, graph):
    """Check the (LB) 4-point certificate. Returns True if valid."""
    n = len(order)
    for ia in range(n):
        a = order[ia]
        for ib in range(ia + 1, n):
            b = order[ib]
            for ic in range(ib + 1, n):
                c = order[ic]
                if graph[a][c] and not graph[a][b]:
                    found = False
                    for id_ in range(ia):
                        d = order[id_]
                        if graph[d][b] and not graph[d][c]:
                            found = True
                            break
                    if not found:
                        return False
    return True


def _try_insert_repair(order, graph, u, v):
    """Try to repair the ordering after inserting edge (u, v).

    The insertion only changes the neighbor sets of u and v.  In a LexBFS
    ordering, the relative order of u and v is determined by their labels.
    After adding the edge, the only possible change is the relative order
    of u and v.  So we try: keep current order, or swap u and v.
    """
    n = len(order)
    pos = {v: i for i, v in enumerate(order)}
    pu, pv = pos[u], pos[v]

    candidates = [list(order)]
    swapped = list(order)
    swapped[pu], swapped[pv] = swapped[pv], swapped[pu]
    candidates.append(swapped)

    for cand in candidates:
        if _is_lexbfs(cand, graph):
            return cand
    return None


def init(graph):
    order = _lexbfs(graph)
    return {'ordering': order}


def insert_edge(graph, edge, state):
    u, v = edge
    order = state['ordering']
    repaired = _try_insert_repair(order, graph, u, v)
    if repaired is not None:
        return {'ordering': repaired}
    return {'ordering': _lexbfs(graph)}


def delete_edge(graph, edge, state):
    return {'ordering': _lexbfs(graph)}

